import math
def control(obs):
    h = obs['hitch_deg']
    views = obs.get('views', {})
    cam = views.get('camera') or {}
    pts = cam.get('walls', [])
    left = []
    right = []
    for b, d in pts:
        x = d * math.cos(math.radians(b))
        y = d * math.sin(math.radians(b))
        if x < -3 and x > -11:
            (left if y > 0 else right).append(y)
    desired = 0.0
    if left and right:
        center = (sum(left)/len(left) + sum(right)/len(right))/2
        desired = max(-12, min(12, center * 2.0))
    steer = max(-30, min(30, 2.0*(h-desired)))
    return (steer, -0.7, -41)

